cd /workspace/tmp && python3 - << 'EOF'
import json, random, sys, time
sys.path.insert(0,'/workspace/tmp'); sys.path.insert(0,'/workspace/submission')
import main as impl

def mk(services, specs, comb='and', op='contains', extra_services=True):
    rules = []
    if comb == 'and':
        when = {'op':'and','args':[{'op':op,'path':list(p)} for p in specs]}
    elif comb == 'or':
        when = {'op':'or','args':[{'op':op,'path':list(p)} for p in specs]}
    else:
        when = {'op':op,'path':list(specs[0])}
    rules.append({'action':'allow','when':when})
    svc = list(services)
    if extra_services and len(svc) < 24:
        svc = svc + ['s%d' % i for i in range(24 - len(svc))]
    queries = [[svc[0]]*3]
    return {'services':svc,'rules':rules,'queries':queries}

rng = random.Random(11)
for k in (7,8,9):
    specs = [tuple(rng.choice(['a','b']) for _ in range(16)) for _ in range(k)]
    req = mk(['a','b'], specs)
    parsed = impl.parse_request(json.loads(json.dumps(req)))
    t0=time.time()
    try:
        order, trans, const_truth, kept, truth, nrep, col_of = impl.build_product(parsed['atoms'], len(parsed['services']))
        prod = len(order)
    except impl.ComplexityError:
        print('k=%d product>20000'%k); continue
    t1=time.time()
    out = impl.compile_bundle(parsed)
    t2=time.time()
    o = json.loads(out)
    print('k=%d product=%d minstates=%d nrep=%d build=%.2fs total=%.2fs outlen=%d' % (
        k, prod, len(o['dfa']['next']), nrep, t1-t0, t2-t0, len(out)))
EOF
